app.post('/api/admin/users',allow('admin'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const d=req.body;const email=text(d.email,254).toLowerCase(),name=text(d.name,120),role=roles.includes(d.role)?d.role:null,password=String(d.password||'');if(!email.includes('@')||!name||!role||password.length<14)return fail(res,400,'Informe nome, e-mail, perfil e senha inicial com pelo menos 14 caracteres.');const hash=await bcrypt.hash(password,12);const user={id:id(),name,email,hash,role};await inTx(async c=>{await c.query('INSERT INTO users(id,name,email,password_hash,role) VALUES($1,$2,$3,$4,$5)',Object.values(user));await c.query('INSERT INTO user_units(user_id,unit_id) VALUES($1,$2)',[user.id,u.id]);await audit(c,req,u.id,'create','user',user.id,null,{name,email,role});});res.status(201).json({id:user.id,name,email,role});}catch(e){if(e.code==='23505')return fail(res,409,'Já existe usuário com este e-mail.');next(e);}});

app.get('/api/settings',async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const r=await pool.query(`SELECT setting_key,setting_value,effective_from FROM app_settings WHERE unit_id=$1 ORDER BY effective_from DESC`,[u.id]);const result={};for(const row of r.rows)if(!(row.setting_key in result))result[row.setting_key]={value:row.setting_value,effective_from:row.effective_from};res.json(result);}catch(e){next(e);}});
app.post('/api/settings',allow('admin','owner'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const target=parseMoney(req.body.purchase_target_percent);if(target===null||target<0||target>10000)return fail(res,400,'A meta percentual deve estar entre 0% e 100%.');const effective=validDate(req.body.effective_from)?req.body.effective_from:localToday();const setting={id:id(),unit_id:u.id,setting_key:'purchase_target_percent',setting_value:JSON.stringify(target/100),effective_from:effective,created_by:req.session.user.id};await pool.query(`INSERT INTO app_settings(id,unit_id,setting_key,setting_value,effective_from,created_by) VALUES($1,$2,$3,$4::jsonb,$5,$6) ON CONFLICT(unit_id,setting_key,effective_from) DO UPDATE SET setting_value=EXCLUDED.setting_value,created_by=EXCLUDED.created_by`,Object.values(setting));await audit(pool,req,u.id,'update','setting',setting.id,null,{purchase_target_percent:target/100,effective_from:effective});res.json({purchase_target_percent:target/100,effective_from:effective});}catch(e){next(e);}});

app.post('/api/import/preview',allow('admin','owner','finance'),upload.single('file'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;if(!req.file)return fail(res,400,'Escolha uma planilha XLSX.');if(!req.file.originalname.toLowerCase().endsWith('.xlsx'))return fail(res,400,'Somente arquivos .xlsx são aceitos nesta versão.');const kind=['sales','expenses','products'].includes(req.body.import_type)?req.body.import_type:null;if(!kind)return fail(res,400,'Escolha o tipo de importação.');const wb=new ExcelJS.Workbook();await wb.xlsx.load(req.file.buffer);const sheetName=text(req.body.sheet_name||wb.worksheets[0]?.name,120);const sheet=wb.getWorksheet(sheetName);if(!sheet)return fail(res,400,'A aba escolhida não existe.');if(sheet.rowCount>10001)return fail(res,413,'A aba excede o limite de 10.000 linhas.');const headers=sheet.getRow(1).values.slice(1).map((_,i)=>text(sheet.getRow(1).getCell(i+1).text,200));const mappedHeaders=headers.map((h,i)=>h||`Coluna ${i+1}`);const rows=[];for(let n=2;n<=sheet.rowCount;n++){const row={};let hasData=false;for(let i=0;i<mappedHeaders.length;i++){const value=sheet.getRow(n).getCell(i+1).text;row[mappedHeaders[i]]=value===''?null:value;if(value!=='')hasData=true;}if(hasData)rows.push(row);}if(!mappedHeaders.length||!rows.length)return fail(res,400,'A aba precisa ter cabeçalho e linhas de dados para pré-visualizar.');const batch={id:id(),unit_id:u.id,user_id:req.session.user.id,source_name:path.basename(req.file.originalname).slice(0,200),sheet_name:sheetName,import_type:kind,headers:JSON.stringify(mappedHeaders),rows_data:JSON.stringify(rows)};await pool.query(`INSERT INTO import_batches(id,unit_id,user_id,source_name,sheet_name,import_type,headers,rows_data) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb,$8::jsonb)`,Object.values(batch));await audit(pool,req,u.id,'preview','import_batch',batch.id,null,{source_name:batch.source_name,sheet:sheetName,kind,rows:rows.length});res.status(201).json({id:batch.id,source_name:batch.source_name,sheet:sheetName,kind,headers:mappedHeaders,rows:rows.slice(0,15),total_rows:rows.length});}catch(e){if(e instanceof multer.MulterError)return fail(res,413,'Arquivo muito grande.');next(e);}});
app.post('/api/import/:id/commit',allow('admin','owner','finance'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const result=await inTx(async c=>{const b=await c.query('SELECT * FROM import_batches WHERE id=$1 AND unit_id=$2 AND user_id=$3 AND status=$4 FOR UPDATE',[req.params.id,u.id,req.session.user.id,'draft']);if(!b.rowCount)return {error:'Rascunho de importação não encontrado ou já processado.'};const mapping=req.body.mapping||{};const rows=b.rows[0].rows_data;let imported=0;const rejected=[];for(let i=0;i<rows.length;i++){const src=rows[i];const get=k=>src[mapping[k]];await c.query('SAVEPOINT import_row');try{if(b.rows[0].import_type==='sales'){const amount=parseMoney(get('amount')),date=normalizeDate(get('sale_date'));if(amount===null||!date)throw Error('data ou valor inválido');await c.query('INSERT INTO sales(id,unit_id,sale_date,channel,amount_cents,target_cents,notes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8)',[id(),u.id,date,text(get('channel')||'Importado',80),amount,parseMoney(get('target')),text(get('notes'),1000),req.session.user.id]);}
        else if(b.rows[0].import_type==='expenses'){const amount=parseMoney(get('total')),issue=normalizeDate(get('issue_date')),due=normalizeDate(get('due_date')),supplier=text(get('supplier'),160),description=text(get('description')||supplier,250);if(amount===null||!issue||!supplier)throw Error('fornecedor, data ou valor inválido');await c.query('INSERT INTO expenses(id,unit_id,supplier,document_number,issue_date,accrual_date,description,total_cents,due_date,status,created_by) VALUES($1,$2,$3,$4,$5,$5,$6,$7,$8,\'open\',$9)',[id(),u.id,supplier,text(get('document_number'),100)||null,issue,description,amount,due,req.session.user.id]);}
        else {const name=text(get('name'),160),sku=text(get('sku'),80)||null;if(!name)throw Error('nome do produto ausente');await c.query('INSERT INTO products(id,unit_id,name,sku,base_unit,created_by) VALUES($1,$2,$3,$4,$5,$6)',[id(),u.id,name,sku,text(get('unit')||'unidade',30),req.session.user.id]);}
        imported++;await c.query('RELEASE SAVEPOINT import_row');
      }catch(err){await c.query('ROLLBACK TO SAVEPOINT import_row');await c.query('RELEASE SAVEPOINT import_row');rejected.push({line:i+2,message:text(err.message,200)});}}
      const status=imported===rows.length?'completed':imported?'partial':'partial';const report={total:rows.length,imported,rejected};await c.query('UPDATE import_batches SET status=$1,report=$2::jsonb,completed_at=now() WHERE id=$3',[status,JSON.stringify(report),req.params.id]);await audit(c,req,u.id,'commit','import_batch',req.params.id,null,report);return report;});if(result.error)return fail(res,404,result.error);res.json(result);}catch(e){next(e);}});

app.post('/api/attachments',allow('admin','owner','finance','operations'),upload.single('file'),async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;if(!req.file)return fail(res,400,'Escolha um arquivo.');const type=text(req.body.entity_type,20),entity=text(req.body.entity_id,100);if(!['expense','cash','sale'].includes(type)||!entity)return fail(res,400,'Informe o lançamento relacionado.');if(type==='expense'&&!['admin','owner','finance'].includes(req.session.user.role))return fail(res,403,'Seu perfil não pode acessar anexos de despesas.');const allowed=type==='expense'?['application/pdf','image/jpeg','image/png']:['application/pdf','image/jpeg','image/png'];if(!allowed.includes(req.file.mimetype))return fail(res,415,'Formato não aceito. Envie PDF, JPG ou PNG.');const b=req.file.buffer;const signature=req.file.mimetype==='application/pdf'?b.subarray(0,5).toString()==='%PDF-':req.file.mimetype==='image/png'?b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])):b[0]===0xff&&b[1]===0xd8&&b[2]===0xff;if(!signature)return fail(res,415,'O conteúdo do arquivo não corresponde ao formato declarado.');const table={expense:'expenses',cash:'cash_movements',sale:'sales'}[type];const valid=await pool.query(`SELECT id FROM ${table} WHERE id=$1 AND unit_id=$2`,[entity,u.id]);if(!valid.rowCount)return fail(res,404,'Registro relacionado não encontrado.');const dir=path.resolve(process.env.UPLOAD_DIR||path.join(__dirname,'data','uploads'));await fs.mkdir(dir,{recursive:true});const stored=id();await fs.writeFile(path.join(dir,stored),b,{flag:'wx'});const row={id:stored,unit_id:u.id,entity_type:type,entity_id:entity,original_name:path.basename(req.file.originalname).slice(0,200),stored_name:stored,mime_type:req.file.mimetype,size_bytes:req.file.size,created_by:req.session.user.id};await inTx(async c=>{await c.query('INSERT INTO attachments(id,unit_id,entity_type,entity_id,original_name,stored_name,mime_type,size_bytes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)',Object.values(row));await audit(c,req,u.id,'upload','attachment',row.id,null,{entity_type:type,entity_id:entity,name:row.original_name,size_bytes:row.size_bytes});});res.status(201).json({id:row.id,name:row.original_name,mime_type:row.mime_type,size_bytes:row.size_bytes});}catch(e){if(e instanceof multer.MulterError)return fail(res,413,'Arquivo excede o limite permitido.');next(e);}});
app.get('/api/attachments/:id',async(req,res,next)=>{try{const u=await routeUnit(req,res);if(!u)return;const r=await pool.query('SELECT * FROM attachments WHERE id=$1 AND unit_id=$2',[req.params.id,u.id]);if(!r.rowCount)return fail(res,404,'Anexo não encontrado.');const row=r.rows[0];if(row.entity_type==='expense'&&!['admin','owner','finance','auditor'].includes(req.session.user.role))return fail(res,403,'Seu perfil não pode acessar este anexo.');const dir=path.resolve(process.env.UPLOAD_DIR||path.join(__dirname,'data','uploads'));const file=path.join(dir,row.stored_name);res.setHeader('Content-Type',row.mime_type);res.setHeader('Content-Disposition',`inline; filename*=UTF-8''${encodeURIComponent(row.original_name)}`);res.setHeader('X-Content-Type-Options','nosniff');await audit(pool,req,u.id,'download','attachment',row.id,null,{name:row.original_name});res.sendFile(file);}catch(e){next(e);}});

app.get('/healthz',async(req,res)=>{try{await pool.query('SELECT 1');res.json({ok:true});}catch{res.status(503).json({ok:false});}});

app.use(express.static(path.join(__dirname,'public'),{index:'index.html',maxAge:isProd?'1h':0}));
app.get('/{*path}',(req,res,next)=>{if(req.path.startsWith('/api/'))return fail(res,404,'Rota não encontrada.');res.sendFile(path.join(__dirname,'public','index.html'),e=>e&&next(e));});
app.use((err,req,res,next)=>{console.error(JSON.stringify({level:'error',request_id:req.id,message:err.message,code:err.code}));if(res.headersSent)return next(err);const status=err.status||500;res.status(status).json({error:status>=500?'Erro interno. Informe o código de atendimento.':err.message,request_id:req.id});});

async function bootstrap() {
  if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL não configurada.');
  if (!process.env.SESSION_SECRET || process.env.SESSION_SECRET.length < 32 || process.env.SESSION_SECRET.startsWith('generate-a-unique')) throw new Error('Configure SESSION_SECRET como um segredo aleatório único com pelo menos 32 caracteres.');
  await migrate();
  await pool.query(`INSERT INTO business_units(id,name) VALUES('villa-cruz','Villa Cruz') ON CONFLICT(id) DO NOTHING`);
  const count=await pool.query('SELECT count(*)::int n FROM users');
  if(count.rows[0].n===0){const email=text(process.env.ADMIN_EMAIL,254).toLowerCase(),password=String(process.env.ADMIN_PASSWORD||'');if(!email.includes('@')||password.length<14)throw new Error('Banco sem usuários: configure ADMIN_EMAIL e ADMIN_PASSWORD (mínimo 14 caracteres) para criar o primeiro administrador.');const userId=id(),hash=await bcrypt.hash(password,12);await pool.query('INSERT INTO users(id,name,email,password_hash,role) VALUES($1,$2,$3,$4,$5)',[userId,'Administrador Villa Cruz',email,hash,'admin']);await pool.query("INSERT INTO user_units(user_id,unit_id) VALUES($1,'villa-cruz')",[userId]);console.log('Primeiro administrador criado a partir das variáveis de ambiente.');}
  const defaults=[['Faturamento','income',null],['Impostos e taxas','expense','deduction'],['CMV (regra pendente)','expense','cmv'],['Pessoal','expense','personnel'],['Operacional','expense','operating'],['Administrativa','expense','administrative'],['Ocupação','expense','occupancy'],['Financeira','expense','financial'],['Sem classificação','expense','other'],['Insumos','stock',null]];
  for(const [name,kind,group] of defaults)await pool.query(`INSERT INTO categories(id,unit_id,name,kind,dre_group) VALUES($1,'villa-cruz',$2,$3,$4) ON CONFLICT(unit_id,name,kind) DO NOTHING`,[id(),name,kind,group]);
  app.listen(port,'0.0.0.0',()=>console.log(`Villa Cruz Gestão disponível na porta ${port}`));
}
bootstrap().catch(e=>{console.error('Falha ao iniciar:',e.message);process.exit(1);});
